connection
.
connect
(
)
;
return
(
)
=>
connection
.
disconnect
(
)
;
}
,
[
]
)
;
// 🔴 React Hook useEffect의 의존성 'roomId'가 누락되었습니다.
// ...
}
그리고 린터가 맞을 것입니다!
roomId
는 시간이 지남에 따라 변경될 수 있으므로 코드에 버그가 발생할 수 있습니다.
의존성을 제거하려면 해당 컴포넌트가 의존성이 될
필요가 없다는 것
을 린터에 “증명”하세요.
예를 들어
roomId
를 컴포넌트 밖으로 이동시켜서 반응형 값이 아니고 재렌더링 시에도 변경되지 않음을 증명할 수 있습니다.
